const config = {
  yandexFolderId: 'b1gk4dm4vthtnce2m2ip',
  gptModel: 'yandexgpt-5-lite'
};

// ВАЖНО: нода стоит в разрыве между Webhook и Prepare inputs, поэтому она обязана
// пропускать через себя и json, и binary вебхука. Иначе файлы и текст теряются здесь.
const items = $input.all();
if (!items.length) return [{ json: { config } }];

return items.map(item => ({
  json: { ...item.json, config },
  binary: item.binary
}));

const items = $input.all();
const first = items[0] || { json: {} };
// body приходит с Webhook и пропускается нодой Config без изменений
const body = first.json.body || first.json || {};
const freeText = String(body.text ?? body.freeText ?? body.message ?? '').trim();
const hasBinaryAnywhere = items.some(item => Object.keys(item.binary || {}).length > 0);

const guessMime = (fileName, mimeType) => {
  const value = String(mimeType || '').toLowerCase();
  if (value === 'image/jpg') return 'image/jpeg';
  if (value === 'image/jpeg' || value === 'image/png' || value === 'application/pdf') return value;
  const ext = String(fileName || '').toLowerCase().split('.').pop();
  if (ext === 'png') return 'image/png';
  if (ext === 'pdf') return 'application/pdf';
  return 'image/jpeg';
};

// Здесь ещё не кодируем в base64: сначала картинка должна пройти ресайз,
// поэтому binary переносим под фиксированный ключ data и отдаём дальше как есть.
const out = [];
for (let index = 0; index < items.length; index++) {
  const binary = items[index].binary || {};
  for (const key of Object.keys(binary)) {
    const meta = binary[key] || {};
    out.push({
      json: {
        fileIndex: out.length,
        hasFile: true,
        fileName: meta.fileName || key,
        mimeType: guessMime(meta.fileName, meta.mimeType),
        freeText
      },
      binary: { data: meta }
    });
  }
}

if (!out.length) {
  if (!freeText) {
    throw new Error('Webhook не передал ни файлов, ни текста. Проверьте, что запрос multipart/form-data и что промежуточные ноды пропускают binary.');
  }
  out.push({ json: { fileIndex: 0, hasFile: false, fileName: '', mimeType: null, base64: '', freeText } });
}
if (!out.some(item => item.json.hasFile) && hasBinaryAnywhere) {
  throw new Error('Бинарные данные есть на входе, но не прочитаны.');
}
return out;

const items = $input.all();
const limitBytes = 10 * 1024 * 1024;
const out = [];

for (let index = 0; index < items.length; index++) {
  const item = items[index];
  if (!item.json.hasFile) {
    out.push({ json: { ...item.json, base64: '' } });
    continue;
  }

  const meta = (item.binary || {}).data || {};
  const buffer = await this.helpers.getBinaryDataBuffer(index, 'data');

  if (buffer.length > limitBytes) {
    throw new Error(
      'Файл ' + item.json.fileName + ' весит ' + Math.round(buffer.length / 1048576) +
      ' МБ при лимите Yandex в 10 МБ. Проверьте подготовку файла в виджете; для PDF ресайза нет - уменьшите разрешение скана.'
    );
  }

  const mimeType = String(meta.mimeType || '').toLowerCase();
  out.push({ json: {
    ...item.json,
    mimeType: (mimeType === 'image/jpeg' || mimeType === 'image/png' || mimeType === 'application/pdf') ? mimeType : item.json.mimeType,
    sizeBytes: buffer.length,
    base64: buffer.toString('base64')
  } });
}

return out;

const sources = $('Encode base64').all().map(item => item.json).filter(item => item.hasFile);
const responses = $input.all().map(item => item.json);

// PDF отдаётся постранично: каждая страница - отдельная секция result.
// Собираем все и работаем с первой, но факт многостраничности не замалчиваем.
function findAnnotations(value, found = []) {
  if (!value || typeof value !== 'object') return found;
  const annotation = value.textAnnotation || value.text_annotation;
  if (annotation) {
    found.push(annotation);
    return found;
  }
  for (const child of Object.values(value)) findAnnotations(child, found);
  return found;
}

function blockText(block) {
  const lines = Array.isArray(block.lines) ? block.lines : [];
  const lineText = lines
    .map(line => line.text || (line.words || []).map(word => word.text || '').join(' '))
    .filter(Boolean);
  return String(block.text || lineText.join('\n') || '').trim();
}

function rectOf(block, width, height) {
  const box = block.boundingBox || block.bounding_box || {};
  const vertices = box.vertices || [];
  const xs = vertices.map(vertex => Number(vertex.x || 0));
  const ys = vertices.map(vertex => Number(vertex.y || 0));
  const x1 = xs.length ? Math.min(...xs) : 0;
  const y1 = ys.length ? Math.min(...ys) : 0;
  const x2 = xs.length ? Math.max(...xs) : width;
  const y2 = ys.length ? Math.max(...ys) : height;
  return { x1, y1, x2, y2, cx: (x1 + x2) / 2, cy: (y1 + y2) / 2 };
}

function classify(text) {
  const value = text.toLowerCase();
  let passport = 0;
  let snils = 0;
  // "Российская Федерация" и "дата и место рождения" есть и на СНИЛС,
  // поэтому паспорт опознаём только по тому, чего на СНИЛС быть не может.
  if (/паспорт|кем выдан|код подразделения|личная подпись/.test(value)) passport += 8;
  if (/(у|г)?\s?мвд|уфмс|фмс россии|отделом|отделением|овд|увд/.test(value)) passport += 6;
  if (/^pnrus|<<</.test(value)) passport += 6;
  if (/страховое свидетельство|пенсионного страхования|снилс/.test(value)) snils += 10;
  if (/страховой номер индивидуального|дата регистрации/.test(value)) snils += 6;
  if (passport === 0 && snils === 0) return 'unknown';
  return passport >= snils ? 'passport' : 'snils';
}

const output = [];

for (let index = 0; index < sources.length; index++) {
  const source = sources[index];
  const response = responses[index] || {};
  const annotations = findAnnotations(response);
  const annotation = annotations[0] || null;
  const extraPages = Math.max(0, annotations.length - 1);
  // Yandex Cloud отдаёт отказ как {code, message, details} без ключа error,
  // поэтому пустой ответ без аннотации трактуем как сбой, а не как пустой документ.
  let apiError = null;
  if (response?.error) {
    apiError = String(response.error.message || response.error);
  } else if (!annotation) {
    const message = response?.message || response?.details?.[0]?.message;
    apiError = message ? String(response.code ?? '') + ' ' + String(message) : 'пустой ответ OCR';
    apiError = apiError.trim();
  }

  const width = Number(annotation?.width || 1) || 1;
  const height = Number(annotation?.height || 1) || 1;
  const rawBlocks = Array.isArray(annotation?.blocks) ? annotation.blocks : [];

  let blocks = rawBlocks
    .map((block, blockIndex) => {
      const text = blockText(block);
      return { blockIndex, text, bbox: rectOf(block, width, height), type: classify(text) };
    })
    .filter(block => block.text);

  // Числовые полосы (серия/номер печатаются вертикально) не должны попадать
  // под геометрическую привязку к чужому документу — помечаем их отдельно.
  const numericBlocks = [];
  for (const block of blocks) {
    const stripped = block.text.replace(/[\s\-\u2013\u2014\u2116]/g, '');
    if (/^\d{6,}$/.test(stripped)) {
      numericBlocks.push(stripped);
      // 11 цифр - это потенциальный СНИЛС, тип не перетираем, иначе номер выпадет из snils-региона
      if (stripped.length !== 11) block.type = 'numeric';
    }
  }

  const anchors = blocks.filter(block => block.type === 'passport' || block.type === 'snils');
  for (const block of blocks.filter(block => block.type === 'unknown')) {
    if (!anchors.length) break;
    const nearest = anchors
      .map(anchor => {
        const dx = (block.bbox.cx - anchor.bbox.cx) / width;
        const dy = (block.bbox.cy - anchor.bbox.cy) / height;
        return { anchor, distance: Math.sqrt(dx * dx + dy * dy) };
      })
      .sort((a, b) => a.distance - b.distance)[0];
    if (nearest && nearest.distance <= 0.35) block.type = nearest.anchor.type;
  }

  if (!blocks.length) {
    const fallback = annotation?.fullText || annotation?.full_text || '';
    if (fallback) {
      blocks = [{ blockIndex: 0, text: fallback, bbox: { x1: 0, y1: 0, x2: width, y2: height, cx: width / 2, cy: height / 2 }, type: 'unknown' }];
    }
  }

  output.push({ json: {
    fileIndex: source.fileIndex,
    fileName: source.fileName,
    mimeType: source.mimeType,
    base64: source.base64,
    freeText: source.freeText,
    ocrError: apiError,
    ocrText: blocks.map(block => block.text).join('\n'),
    blockCount: blocks.length,
    extraPages,
    sizeBytes: source.sizeBytes ?? null,
    numericBlocks,
    regions: blocks.map(block => ({
      fileName: source.fileName,
      type: block.type,
      text: block.text,
      bbox: [block.bbox.x1, block.bbox.y1, block.bbox.x2, block.bbox.y2],
      page: { width, height }
    }))
  } });
}

if (!output.length) throw new Error('OCR не вернул ни одного результата.');
return output;

const previous = $('Parse page OCR').all().map(item => item.json);
const responses = $input.all().map(item => item.json);

function findAnnotation(value) {
  if (!value || typeof value !== 'object') return null;
  if (value.textAnnotation) return value.textAnnotation;
  if (value.text_annotation) return value.text_annotation;
  for (const child of Object.values(value)) {
    const found = findAnnotation(child);
    if (found) return found;
  }
  return null;
}

const digits = value => String(value || '').replace(/\D/g, '');
const capitalize = value => (value ? value.charAt(0).toUpperCase() + value.slice(1) : '');

// Контрольный разряд MRZ по схеме 7-3-1
function mrzCheckDigit(value) {
  const weights = [7, 3, 1];
  let sum = 0;
  for (let i = 0; i < value.length; i++) {
    const char = value[i];
    let digit = 0;
    if (char >= '0' && char <= '9') digit = Number(char);
    else if (char >= 'A' && char <= 'Z') digit = char.charCodeAt(0) - 55;
    sum += digit * weights[i % 3];
  }
  return sum % 10;
}

// Внутренний паспорт РФ: первые 9 цифр второй строки MRZ - это 3 цифры серии
// и 6 цифр номера, четвёртая цифра серии стоит сразу после заполнителей '<'.
// К абсолютной позиции не привязываемся: OCR регулярно теряет или добавляет '<'.
function twoDigitYear(value) {
  const year = Number(value);
  const current = new Date().getFullYear() % 100;
  return (year <= current + 1 ? 2000 : 1900) + year;
}
function asDate(value) {
  if (!/^\d{6}$/.test(value)) return null;
  const year = twoDigitYear(value.slice(0, 2));
  const month = value.slice(2, 4);
  const day = value.slice(4, 6);
  if (Number(month) < 1 || Number(month) > 12 || Number(day) < 1 || Number(day) > 31) return null;
  return day + '.' + month + '.' + year;
}
function parseMrz(text) {
  const lines = String(text || '').toUpperCase().split(/\r?\n/).map(line => line.replace(/\s/g, ''));
  for (const line of lines) {
    if (line.length < 35 || !line.includes('<<')) continue;
    const document = line.slice(0, 9);
    if (!/^\d{9}$/.test(document)) continue;

    const control = line[9];
    const checked = /^\d$/.test(control) && mrzCheckDigit(document) === Number(control);

    // после пола идёт блок заполнителей, сразу за ним - четвёртая цифра серии
    const tail = line.slice(20);
    const match = tail.match(/<+(\d)(\d{6})?(\d{6})?/);
    if (!match) continue;

    const departmentDigits = match[3] || '';
    return {
      series: document.slice(0, 3) + match[1],
      number: document.slice(3),
      checked,
      birth_date: asDate(line.slice(13, 19)),
      issue_date: asDate(match[2] || ''),
      department_code: /^\d{6}$/.test(departmentDigits)
        ? departmentDigits.slice(0, 3) + '-' + departmentDigits.slice(3)
        : null
    };
  }
  return null;
}

const output = [];

for (let index = 0; index < previous.length; index++) {
  const base = previous[index];
  const response = responses[index] || {};
  const annotation = findAnnotation(response);

  const entities = {};
  for (const entity of (annotation?.entities || [])) {
    if (entity && entity.name) entities[entity.name] = String(entity.text || '').trim();
  }

  const combined = digits(entities.number);
  // Модель отдаёт код подразделения под именем subdivision.
  const subdivision = digits(entities.subdivision);
  const template = {
    passport_series: combined.length === 10 ? combined.slice(0, 4) : null,
    passport_number: combined.length === 10 ? combined.slice(4) : null,
    full_name: [entities.surname, entities.name, entities.middle_name].filter(Boolean).map(capitalize).join(' ') || null,
    birth_date: entities.birth_date || null,
    birth_place: capitalize(entities.birth_place || '') || null,
    issue_date: entities.issue_date || null,
    issued_by: capitalize(entities.issued_by || '') || null,
    department_code: subdivision.length === 6 ? subdivision.slice(0, 3) + '-' + subdivision.slice(3) : null
  };

  const { base64, ...rest } = base;
  output.push({ json: { ...rest, template, mrz: parseMrz(base.ocrText) } });
}

return output;

const items = $input.all().map(item => item.json);
const digits = value => String(value || '').replace(/\D/g, '');

const freeText = items.map(item => String(item.freeText || '').trim()).find(Boolean) || '';
const ocrText = [...new Set(items.map(item => String(item.ocrText || '').trim()).filter(Boolean))].join('\n');
const regions = items.flatMap(item => (Array.isArray(item.regions) ? item.regions : []));
const numericBlocks = items.flatMap(item => (Array.isArray(item.numericBlocks) ? item.numericBlocks : []));
const templates = items.map(item => item.template).filter(value => value && Object.keys(value).length);
const mrzList = items.map(item => item.mrz).filter(Boolean);
const ocrErrors = items.map(item => (item.ocrError ? item.fileName + ': ' + item.ocrError : null)).filter(Boolean);
for (const item of items) {
  if (item.fileName && !item.ocrError && !String(item.ocrText || '').trim()) {
    ocrErrors.push(item.fileName + ': OCR вернул пустой текст');
  }
  if (item.extraPages) {
    ocrErrors.push(item.fileName + ': в файле ' + (item.extraPages + 1) + ' страниц, разобрана только первая');
  }
}

const combinedText = [ocrText, freeText].filter(Boolean).join('\n\n--- ТЕКСТ ОТ ПОЛЬЗОВАТЕЛЯ ---\n');
// Шаблонная модель может отработать там, где общий OCR вернул пусто (и наоборот),
// поэтому падаем только когда данных нет вообще ни из одного источника.
const hasStructuredData = mrzList.length
  || templates.some(template => Object.values(template).some(Boolean));
if (!combinedText && !hasStructuredData) {
  throw new Error('Не распознан ни один документ и не передан текст.');
}

const snilsRegions = regions.filter(region => region.type === 'snils').map(region => region.text);
// Берём всё, что НЕ опознано как СНИЛС: шапку паспорта OCR часто читает нечитаемо,
// и опора только на passport-регионы приводит к тому, что настоящий паспорт выпадает целиком.
const passportRegions = regions.filter(region => region.type !== 'snils').map(region => region.text);
// Свободный текст пользователя участвует в поиске ВСЕГДА, иначе он теряется при наличии фото.
const passportText = [...passportRegions, ...numericBlocks, freeText].filter(Boolean).join('\n');
const snilsText = [...snilsRegions, freeText].filter(Boolean).join('\n') || combinedText;

const dateYears = [...combinedText.matchAll(/\b\d{1,2}[.\/-]\d{1,2}[.\/-](\d{4})\b/g)].map(match => match[1]);

// NNN-NNN, но только если следом не идёт ещё одна группа цифр: иначе
// регулярка откусывает первые две группы номера СНИЛС (158-407 из 158-407-745 90).
const departmentPattern = /(?<![\d\u2013\u2014-])(\d{3})\s*[-\u2013\u2014]\s*(\d{3})(?![-\u2013\u2014\s]*\d)/;
const departmentMatch = combinedText.match(/код\s*подразделения[^\d]{0,10}(\d{3})\s*[-\u2013\u2014]\s*(\d{3})/i)
  || passportText.match(departmentPattern);
const mrzDepartment = mrzList.map(mrz => mrz.department_code).find(Boolean) || null;
const templateDepartment = templates.map(template => template.department_code).find(Boolean) || null;
const departmentCode = mrzDepartment || templateDepartment
  || (departmentMatch ? departmentMatch[1] + '-' + departmentMatch[2] : null);
const departmentDigits = digits(departmentCode);

// ---- серия и номер: несколько независимых источников, побеждает согласие ----
const rawCandidates = [];
const addCandidate = (series, number, score, source) => {
  if (!/^\d{4}$/.test(String(series || '')) || !/^\d{6}$/.test(String(number || ''))) return;
  if (number === departmentDigits) return;
  const blankYear = Number(String(series).slice(2));
  let adjusted = score;
  if (!(blankYear >= 96 || blankYear <= (new Date().getFullYear() % 100) + 1)) adjusted -= 15;
  if (dateYears.includes(String(series))) adjusted -= 30;
  rawCandidates.push({ series: String(series), number: String(number), score: adjusted, source });
};

for (const mrz of mrzList) addCandidate(mrz.series, mrz.number, mrz.checked ? 100 : 70, 'mrz');
for (const template of templates) addCandidate(template.passport_series, template.passport_number, 80, 'yandex-passport-model');

for (const block of numericBlocks) {
  const value = digits(block);
  if (value.length === 10) addCandidate(value.slice(0, 4), value.slice(4), 55, 'ocr-strip');
  if (value.length === 20 && value.slice(0, 10) === value.slice(10)) addCandidate(value.slice(0, 4), value.slice(4, 10), 65, 'ocr-strip-x2');
}

const patterns = [
  /(?:паспорт[а-я]*[^\d]{0,30})?(?:серия\s*)?(\d{2})[\s-]*(\d{2})[^\d]{0,20}(?:\u2116|N|номер)?[^\d]{0,8}((?:\d[\s-]*){6})(?!\d)/gi,
  /(^|[^\d])(\d{2})[\s\n-]+(\d{2})[\s\n-]+((?:\d[\s-]*){6})(?!\d)/gim
];
patterns.forEach((pattern, patternIndex) => {
  for (const match of passportText.matchAll(pattern)) {
    const offset = patternIndex === 0 ? 0 : 1;
    const series = digits(match[1 + offset] + match[2 + offset]);
    const number = digits(match[3 + offset]);
    const around = passportText.slice(Math.max(0, match.index - 40), match.index + match[0].length + 20);
    const labelled = /паспорт|серия|\u2116|номер/i.test(around);
    const fromUserText = match.index >= passportText.indexOf(freeText) && freeText.length > 0;
    const score = labelled ? (fromUserText ? 90 : 60) : 25;
    addCandidate(series, number, score, labelled ? 'text-labelled' : 'text-loose');
  }
});

const grouped = new Map();
for (const candidate of rawCandidates) {
  const key = candidate.series + candidate.number;
  const entry = grouped.get(key) || { series: candidate.series, number: candidate.number, score: 0, sources: [] };
  entry.score += candidate.score;
  if (!entry.sources.includes(candidate.source)) entry.sources.push(candidate.source);
  grouped.set(key, entry);
}
const ranked = [...grouped.values()].sort((a, b) => b.score - a.score);
const passport = ranked[0] || null;
const conflict = ranked.length > 1 && ranked[1].score >= 55;

// ---- СНИЛС с проверкой контрольной суммы ----
function validSnils(value) {
  const value11 = digits(value);
  if (value11.length !== 11 || /^(\d)\1{9}/.test(value11)) return false;
  let sum = 0;
  for (let i = 0; i < 9; i++) sum += Number(value11[i]) * (9 - i);
  let control = sum < 100 ? sum : (sum > 101 ? sum % 101 : 0);
  if (control > 99) control = 0;
  return control === Number(value11.slice(9));
}
const snilsPattern = /\b\d{3}[-\s]*\d{3}[-\s]*\d{3}[-\s]*\d{2}\b/g;
const findSnils = text => [...String(text || '').matchAll(snilsPattern)].map(match => match[0]);
// Контрольная сумма надёжнее геометрии, поэтому ищем по всему тексту.
const snilsWide = findSnils([...snilsRegions, ...numericBlocks, combinedText].filter(Boolean).join('\n'));
const snilsNarrow = findSnils([...snilsRegions, freeText].filter(Boolean).join('\n'));
const snilsValid = snilsWide.find(validSnils) || null;
// Если OCR перепутал цифру, лучше вернуть номер с пометкой, чем молча потерять его.
const snilsGuess = snilsValid ? null : (snilsNarrow.find(value => digits(value).length === 11) || null);
const snilsRaw = snilsValid || snilsGuess;
const snils = snilsRaw ? digits(snilsRaw).replace(/(\d{3})(\d{3})(\d{3})(\d{2})/, '$1-$2-$3 $4') : null;

// ---- ФИО из паспорта: MRZ задаёт эталон латиницей, кириллицу берём с разворота ----
// Первая строка MRZ содержит фамилию и имена транслитом. Ищем на развороте
// кириллический блок, чья транслитерация совпадает с фамилией, и забираем
// два блока под ним в той же колонке - это имя и отчество.
const TRANSLIT = { А:'A', Б:'B', В:'V', Г:'G', Д:'D', Е:'E', Ё:'E', Ж:'ZH', З:'Z', И:'I', Й:'I',
  К:'K', Л:'L', М:'M', Н:'N', О:'O', П:'P', Р:'R', С:'S', Т:'T', У:'U', Ф:'F', Х:'KH', Ц:'TS',
  Ч:'CH', Ш:'SH', Щ:'SHCH', Ъ:'IE', Ы:'Y', Ь:'', Э:'E', Ю:'IU', Я:'IA' };
const translit = text => String(text).toUpperCase().split('').map(char => TRANSLIT[char] ?? '').join('');

function similarity(first, second) {
  if (!first || !second) return 0;
  const rows = first.length + 1;
  const cols = second.length + 1;
  const table = Array.from({ length: rows }, () => new Array(cols).fill(0));
  for (let i = 1; i < rows; i++) {
    for (let j = 1; j < cols; j++) {
      table[i][j] = first[i - 1] === second[j - 1]
        ? table[i - 1][j - 1] + 1
        : Math.max(table[i - 1][j], table[i][j - 1]);
    }
  }
  return table[first.length][second.length] / Math.max(first.length, second.length);
}

function nameFromRegions() {
  const mrzLine = combinedText.toUpperCase().match(/PN[A-Z0-9]{3}([A-Z0-9<]{6,})/);
  if (!mrzLine) return null;
  const [surnameLatin] = mrzLine[1].split('<<');
  if (!surnameLatin || surnameLatin.length < 3) return null;

  const words = regions
    .filter(region => region.type !== 'snils' && /^[А-ЯЁ][А-ЯЁ-]{2,}$/.test(String(region.text).trim()))
    .map(region => ({
      text: String(region.text).trim(),
      file: region.fileName,
      cx: (region.bbox[0] + region.bbox[2]) / 2,
      cy: (region.bbox[1] + region.bbox[3]) / 2,
      width: region.page?.width || 1
    }));
  if (!words.length) return null;

  const ranked = words
    .map(word => ({ word, score: similarity(translit(word.text), surnameLatin) }))
    .sort((a, b) => b.score - a.score);
  if (!ranked.length || ranked[0].score < 0.6) return null;

  const surname = ranked[0].word;
  const column = words
    .filter(word => word.file === surname.file && word.cy > surname.cy)
    .filter(word => Math.abs(word.cx - surname.cx) <= surname.width * 0.12)
    .sort((a, b) => a.cy - b.cy)
    .slice(0, 2);

  const capitalize = value => value.charAt(0) + value.slice(1).toLowerCase();
  return [surname, ...column].map(word => capitalize(word.text)).join(' ');
}

// ---- орган выдачи: якорный блок плюс его продолжение на следующих строках ----
function issuerFromRegions() {
  const candidates = regions.filter(region =>
    region.type !== 'snils' && /МВД|УФМС|ФМС|ОВД|УВД|ОТДЕЛ|ОТДЕЛЕНИ/i.test(String(region.text)));
  if (!candidates.length) return null;
  const anchor = candidates[0];
  const height = Math.abs(anchor.bbox[3] - anchor.bbox[1]) || 12;
  const tail = regions
    .filter(region => region.fileName === anchor.fileName && region.bbox[1] > anchor.bbox[1])
    .filter(region => region.bbox[1] - anchor.bbox[3] < height * 2.5)
    .filter(region => /^[А-ЯЁ\s.-]{3,}$/.test(String(region.text).trim()))
    .sort((a, b) => a.bbox[1] - b.bbox[1])
    .slice(0, 1);
  return [anchor, ...tail].map(region => String(region.text).trim()).join(' ').replace(/\s{2,}/g, ' ');
}

// ---- поля из свободного текста ----
const lines = freeText.split(/\r?\n/).map(line => line.trim()).filter(Boolean);
const nameLine = lines.find(line => /^[А-ЯЁ][а-яё-]+\s+[А-ЯЁ][а-яё-]+\s+[А-ЯЁ][а-яё-]+/.test(line));
const fullName = (nameLine ? nameLine.replace(/\(.*?\)/g, '').replace(/\s{2,}/g, ' ').trim() : null)
  || (templates.find(t => t.full_name)?.full_name || null)
  || nameFromRegions();

const mrzBirthDate = mrzList.map(mrz => mrz.birth_date).find(Boolean) || null;
const mrzIssueDate = mrzList.map(mrz => mrz.issue_date).find(Boolean) || null;
const birthDate = mrzBirthDate
  || (combinedText.match(/дата\s*рождения\s*[:\-]?\s*(\d{1,2}[.\/-]\d{1,2}[.\/-]\d{4})/i) || [])[1]
  || templates.find(t => t.birth_date)?.birth_date || null;
const issueMatch = combinedText.match(/выдан[а-я]*\s+(.{5,120}?)\s+(\d{1,2}[.\/-]\d{1,2}[.\/-]\d{4})/i);
const email = (combinedText.match(/[\w.+-]+@[\w-]+\.[\w.-]+/) || [])[0] || null;
const deliveryAddress = lines.find(line => /^\d{6}\s*,/.test(line)) || null;

const consumed = [nameLine, deliveryAddress].filter(Boolean);
const leftoverLines = lines.filter(line =>
  !consumed.includes(line) &&
  !/паспорт|снилс/i.test(line) &&
  !(email && line.includes(email)) &&
  !/^дата\s*рождения/i.test(line) &&
  /[А-Яа-яЁё]{4,}/.test(line)
);

const files = items.filter(item => item.fileName).map(item => ({
  fileName: item.fileName,
  ocrError: item.ocrError || null,
  sizeBytes: item.sizeBytes ?? null,
  textLength: String(item.ocrText || '').length,
  blockCount: item.blockCount ?? 0,
  extraPages: item.extraPages ?? 0,
  regionTypes: [...new Set((item.regions || []).map(region => region.type))],
  numericBlocks: (item.numericBlocks || []).length,
  templateMatched: Boolean(item.template && item.template.passport_number),
  mrzMatched: Boolean(item.mrz)
}));

return [{ json: {
  combinedText,
  regions,
  files,
  ocrErrors,
  leftoverLines,
  candidates: {
    full_name: fullName,
    birth_date: birthDate,
    birth_place: templates.find(t => t.birth_place)?.birth_place || null,
    passport_series: passport ? passport.series : null,
    passport_number: passport ? passport.number : null,
    passport_sources: passport ? passport.sources : [],
    passport_conflict: conflict,
    issue_date: mrzIssueDate || (templates.find(t => t.issue_date)?.issue_date || null) || (issueMatch ? issueMatch[2] : null),
    issued_by: (issueMatch ? issueMatch[1] : null)
      || (templates.find(t => t.issued_by)?.issued_by || null)
      || issuerFromRegions(),
    department_code: departmentCode,
    delivery_address: deliveryAddress,
    email,
    snils,
    snils_checksum_ok: Boolean(snilsValid),
    date_years: dateYears
  }
} }];

const upstream = $('Build GPT request').first().json;
const candidates = upstream.candidates || {};
const response = $json;

const digits = value => String(value || '').replace(/\D/g, '');
const clean = value => {
  const text = String(value ?? '').trim();
  return text && text !== '-' && text.toLowerCase() !== 'null' ? text : null;
};

let parsed = {};
let gptError = null;
try {
  const text = response.result?.alternatives?.[0]?.message?.text
    || response.alternatives?.[0]?.message?.text
    || '';
  const start = text.indexOf('{');
  const end = text.lastIndexOf('}');
  if (start < 0 || end <= start) throw new Error('в ответе YandexGPT нет JSON');
  parsed = JSON.parse(text.slice(start, end + 1));
} catch (error) {
  // Модель недоступна или ответила мусором - отдаём детерминированный результат.
  gptError = String(error.message || error);
  parsed = {};
}

const seriesOf = value => (digits(value).length === 4 ? digits(value) : null);
const numberOf = value => (digits(value).length === 6 ? digits(value) : null);
const departmentOf = value => {
  const value6 = digits(value);
  return value6.length === 6 ? value6.slice(0, 3) + '-' + value6.slice(3) : null;
};
const snilsOf = value => {
  const value11 = digits(value);
  return value11.length === 11
    ? value11.slice(0, 3) + '-' + value11.slice(3, 6) + '-' + value11.slice(6, 9) + ' ' + value11.slice(9)
    : null;
};

// Детерминированный разбор приоритетнее модели для всех числовых полей.
let passportSeries = seriesOf(candidates.passport_series) || seriesOf(parsed.passport_series);
let passportNumber = numberOf(candidates.passport_number) || numberOf(parsed.passport_number);
let departmentCode = departmentOf(candidates.department_code) || departmentOf(parsed.department_code);

// Частая ошибка модели: код подразделения и серия меняются местами.
if (!passportSeries && digits(parsed.department_code).length === 4) passportSeries = seriesOf(parsed.department_code);
if (!departmentCode && digits(parsed.passport_series).length === 6) departmentCode = departmentOf(parsed.passport_series);
if (passportNumber && departmentCode && passportNumber === digits(departmentCode)) passportNumber = null;

const result = {
  full_name: clean(candidates.full_name) || clean(parsed.full_name),
  birth_date: clean(candidates.birth_date) || clean(parsed.birth_date),
  birth_place: clean(parsed.birth_place) || clean(candidates.birth_place),
  passport_series: passportSeries,
  passport_number: passportNumber,
  issue_date: clean(parsed.issue_date) || clean(candidates.issue_date),
  issued_by: clean(parsed.issued_by) || clean(candidates.issued_by),
  department_code: departmentCode,
  registration_address: clean(parsed.registration_address),
  delivery_address: clean(candidates.delivery_address) || clean(parsed.delivery_address),
  program_name: clean(parsed.program_name),
  snils: snilsOf(candidates.snils) || snilsOf(parsed.snils),
  email: clean(candidates.email) || clean(parsed.email)
};

const required = ['full_name', 'birth_date', 'passport_series', 'passport_number', 'issue_date', 'department_code', 'program_name'];
const warnings = [];
for (const field of required) if (!result[field]) warnings.push('missing:' + field);
if (candidates.passport_conflict) warnings.push('conflict:passport_series_number');
if (result.passport_series && (candidates.date_years || []).includes(result.passport_series)) warnings.push('suspicious:passport_series_looks_like_year');
if (result.snils && !candidates.snils_checksum_ok) warnings.push('suspicious:snils_checksum_failed');
if (gptError) warnings.push('gpt_unavailable:' + gptError);
for (const error of (upstream.ocrErrors || [])) warnings.push('ocr:' + error);

// Возврат исходников по запросу: base64 раздувает ответ примерно на треть,
// поэтому только если клиент прислал includeFiles=1 в теле запроса.
let files = [];
try {
  const body = $('Config').first().json?.body || {};
  const wanted = body.includeFiles ?? body.include_files;
  if (wanted && String(wanted) !== '0' && String(wanted) !== 'false') {
    files = $('Encode base64').all()
      .map(item => item.json)
      .filter(item => item.hasFile && item.base64)
      .map(item => ({
        fileName: item.fileName,
        mimeType: item.mimeType,
        sizeBytes: item.sizeBytes ?? null,
        base64: item.base64
      }));
  }
} catch (error) {
  // Ветка без файлов - ноды кодирования в этом выполнении не было.
}

return [{ json: {
  ...result,
  files,
  meta: {
    files: upstream.files || [],
    passport_sources: candidates.passport_sources || [],
    needs_review: warnings.length > 0,
    warnings
  }
} }];
